package org.beyondlight;
import java.util.*;
/** Small immutable expression tree. Unsupported symbolic transforms fail explicitly. */
public final class Symbolic {
 public record Node(String op,String atom,Node left,Node right) { }
 private final String s;private int p;private Symbolic(String s){this.s=s;}
 public static Node parse(String text){if(text==null||text.length()>4096)throw new IllegalArgumentException("expression missing or exceeds 4096 characters");Symbolic p=new Symbolic(text);Node n=p.sum();p.ws();if(p.p!=text.length())throw p.err("unexpected token");return simplify(n);}
 public static String canonical(String s){return print(parse(s));}
 public static double evaluate(String s,Map<String,Double> vars){return evaluate(parse(s),vars);}
 public static double evaluate(Node n,Map<String,Double> vars){double x=eval(n,vars);if(!Double.isFinite(x))throw new IllegalArgumentException("evaluation result is outside the finite real domain");return x;}
 public static String derivative(String s,String variable){return print(simplify(diff(parse(s),variable)));}
 public static String substitute(String s,String variable,String replacement){return print(simplify(sub(parse(s),variable,parse(replacement))));}
 public static String integrate(String s,String variable){return print(simplify(integral(parse(s),variable)));}
 public static String simplifyText(String s){return print(simplify(parse(s)));}
 public static String isolate(String lhs,String rhs,String variable){Node l=parse(lhs),r=parse(rhs);if(has(l,variable)&&!has(r,variable))return print(simplify(solve(l,variable,r)));if(has(r,variable)&&!has(l,variable))return print(simplify(solve(r,variable,l)));throw new IllegalArgumentException("isolation needs target variable on exactly one side and a supported invertible operation");}
 private Node sum(){Node n=prod();while(true){ws();if(take('+'))n=new Node("+",null,n,prod());else if(take('-'))n=new Node("-",null,n,prod());else return n;}}
 private Node prod(){Node n=power();while(true){ws();if(take('*'))n=new Node("*",null,n,power());else if(take('/'))n=new Node("/",null,n,power());else return n;}}
 private Node power(){Node n=unary();ws();if(take('^'))n=new Node("^",null,n,power());return n;}
 private Node unary(){ws();if(take('+'))return unary();if(take('-'))return new Node("neg",null,unary(),null);if(take('(')){Node n=sum();ws();if(!take(')'))throw err("expected )");return n;}if(p<s.length()&&(Character.isDigit(s.charAt(p))||s.charAt(p)=='.'))return c(number());int a=p;while(p<s.length()&&(Character.isLetterOrDigit(s.charAt(p))||s.charAt(p)=='_'))p++;if(a==p)throw err("expected symbol");String id=s.substring(a,p);ws();if(take('(')){Node n=sum();ws();if(!take(')'))throw err("expected )");if(!Set.of("sqrt","ln","exp","sin","cos").contains(id))throw err("unsupported function "+id);return new Node(id,null,n,null);}return new Node("var",id,null,null);}
 private double number(){int a=p;while(p<s.length()&&(Character.isDigit(s.charAt(p))||".eE".indexOf(s.charAt(p))>=0)){if((s.charAt(p)=='+'||s.charAt(p)=='-')&&p>a&&"eE".indexOf(s.charAt(p-1))<0)break;p++;}try{double x=Double.parseDouble(s.substring(a,p));if(!Double.isFinite(x))throw err("nonfinite literal");return x;}catch(NumberFormatException e){throw err("invalid number");}}
 private void ws(){while(p<s.length()&&Character.isWhitespace(s.charAt(p)))p++;}private boolean take(char c){if(p<s.length()&&s.charAt(p)==c){p++;return true;}return false;}private IllegalArgumentException err(String s){return new IllegalArgumentException(s+" at column "+(p+1));}
 private static Node c(double x){return new Node("num",Double.toString(x),null,null);}private static Node v(String x){return new Node("var",x,null,null);}private static boolean num(Node n){return n.op.equals("num");}private static double val(Node n){return Double.parseDouble(n.atom);}private static Node simplify(Node n){if(n.left==null)return n;Node a=simplify(n.left),b=n.right==null?null:simplify(n.right);if(n.op.equals("neg")){if(num(a))return c(-val(a));if(a.op.equals("neg"))return a.left;return new Node(n.op,null,a,null);}if(b!=null&&num(a)&&num(b)){double x=val(a),y=val(b),z=switch(n.op){case "+"->x+y;case "-"->x-y;case "*"->x*y;case "/"->x/y;case "^"->Math.pow(x,y);default->Double.NaN;};if(Double.isFinite(z))return c(z);}if(n.op.equals("+")){if(num(a)&&val(a)==0)return b;if(num(b)&&val(b)==0)return a;}if(n.op.equals("-")){if(num(b)&&val(b)==0)return a;}if(n.op.equals("*")){if((num(a)&&val(a)==0)||(num(b)&&val(b)==0))return c(0);if(num(a)&&val(a)==1)return b;if(num(b)&&val(b)==1)return a;}if(n.op.equals("/")&&num(b)&&val(b)==1)return a;if(n.op.equals("^")&&num(b)&&val(b)==1)return a;if(n.op.equals("^")&&num(b)&&val(b)==0)return c(1);return new Node(n.op,n.atom,a,b);}
 private static String print(Node n){if(n.op.equals("num")||n.op.equals("var"))return n.atom;if(n.op.equals("neg"))return "(-"+print(n.left)+")";if(n.right==null)return n.op+"("+print(n.left)+")";return "("+print(n.left)+n.op+print(n.right)+")";}
 private static boolean has(Node n,String x){return n.op.equals("var")&&n.atom.equals(x)||n.left!=null&&has(n.left,x)||n.right!=null&&has(n.right,x);}
 private static Node sub(Node n,String x,Node r){if(n.op.equals("var")&&n.atom.equals(x))return r;if(n.left==null)return n;return simplify(new Node(n.op,n.atom,sub(n.left,x,r),n.right==null?null:sub(n.right,x,r)));}
 private static double eval(Node n,Map<String,Double> m){if(n.op.equals("num"))return val(n);if(n.op.equals("var")){if(n.atom.equals("pi"))return Math.PI;if(n.atom.equals("e"))return Math.E;if(!m.containsKey(n.atom))throw new IllegalArgumentException("undefined variable "+n.atom);return m.get(n.atom);}double a=eval(n.left,m);if(n.op.equals("neg"))return -a;if(n.right==null)return switch(n.op){case "sqrt"->Math.sqrt(a);case "ln"->Math.log(a);case "exp"->Math.exp(a);case "sin"->Math.sin(a);case "cos"->Math.cos(a);default->throw new IllegalArgumentException("unsupported operation");};double b=eval(n.right,m);return switch(n.op){case "+"->a+b;case "-"->a-b;case "*"->a*b;case "/"->a/b;case "^"->Math.pow(a,b);default->throw new IllegalArgumentException("unsupported operation");};}
 private static Node diff(Node n,String x){if(n.op.equals("num")||n.op.equals("var")&&!n.atom.equals(x))return c(0);if(n.op.equals("var"))return c(1);Node a=n.left,b=n.right;if(n.op.equals("neg"))return new Node("neg",null,diff(a,x),null);Node da=diff(a,x),db=b==null?null:diff(b,x);return switch(n.op){case "+"->new Node("+",null,da,db);case "-"->new Node("-",null,da,db);case "*"->new Node("+",null,new Node("*",null,da,b),new Node("*",null,a,db));case "/"->new Node("/",null,new Node("-",null,new Node("*",null,da,b),new Node("*",null,a,db)),new Node("^",null,b,c(2)));case "^"->{if(!has(b,x))yield new Node("*",null,new Node("*",null,b,new Node("^",null,a,new Node("-",null,b,c(1)))),da);throw new IllegalArgumentException("power differentiation requires a variable independent exponent");}case "sin"->new Node("*",null,new Node("cos",null,a,null),da);case "cos"->new Node("neg",null,new Node("*",null,new Node("sin",null,a,null),da),null);case "exp"->new Node("*",null,new Node("exp",null,a,null),da);case "ln"->new Node("/",null,da,a);case "sqrt"->new Node("/",null,da,new Node("*",null,c(2),new Node("sqrt",null,a,null)));default->throw new IllegalArgumentException("derivative unsupported for "+n.op);};}
 private static Node integral(Node n,String x){if(n.op.equals("num"))return new Node("*",null,n,v(x));if(n.op.equals("var")&&n.atom.equals(x))return new Node("/",null,new Node("^",null,v(x),c(2)),c(2));if(n.op.equals("var")||!has(n,x))return new Node("*",null,n,v(x));if(n.op.equals("+")||n.op.equals("-"))return new Node(n.op,null,integral(n.left,x),integral(n.right,x));if(n.op.equals("^")&&n.left.op.equals("var")&&n.left.atom.equals(x)&&n.right.op.equals("num")&&val(n.right)!=-1)return new Node("/",null,new Node("^",null,v(x),c(val(n.right)+1)),c(val(n.right)+1));throw new IllegalArgumentException("basic integrator supports constants, x, sums, and x^n (n != -1)");}
 private static Node solve(Node expr,String x,Node rhs){if(expr.op.equals("var")&&expr.atom.equals(x))return rhs;if(expr.left!=null&&has(expr.left,x)&&!has(expr.right,x)){Node z=expr.right;return switch(expr.op){case "+"->solve(expr.left,x,new Node("-",null,rhs,z));case "-"->solve(expr.left,x,new Node("+",null,rhs,z));case "*"->solve(expr.left,x,new Node("/",null,rhs,z));case "/"->solve(expr.left,x,new Node("*",null,rhs,z));case "^"->{if(!num(z))throw new IllegalArgumentException("variable exponent isolation unsupported");yield solve(expr.left,x,new Node("^",null,rhs,c(1/val(z))));}default->throw new IllegalArgumentException("unsupported rearrangement");};}if(expr.right!=null&&has(expr.right,x)&&!has(expr.left,x)){Node z=expr.left;return switch(expr.op){case "+"->solve(expr.right,x,new Node("-",null,rhs,z));case "-"->solve(expr.right,x,new Node("-",null,z,rhs));case "*"->solve(expr.right,x,new Node("/",null,rhs,z));case "/"->solve(expr.right,x,new Node("/",null,z,rhs));default->throw new IllegalArgumentException("unsupported rearrangement");};}if(expr.right==null&&expr.left!=null&&has(expr.left,x)){Node inverse=switch(expr.op){case "sqrt"->new Node("^",null,rhs,c(2));case "ln"->new Node("exp",null,rhs,null);case "exp"->new Node("ln",null,rhs,null);default->throw new IllegalArgumentException("unsupported inverse function");};return solve(expr.left,x,inverse);}throw new IllegalArgumentException("target variable is not in a supported invertible expression");}
}
